fn reverse(v: &mut Vec<u64>) {
    let n = v.len();
    if n <= 1 {
        // No need to reverse if the vector is empty or has one element
        return;
    }

    // Swap elements from both ends moving towards the center
    let mut left = 0;
    let mut right = n - 1;

    while left < right {
        v.swap(left, right);
        left += 1;
        right -= 1;
    }
}